FuncDef.Code:
// Based on: "Generalized Distance Functions" by Akleman and Chen.
// From: http://mercury.sexy/hg_sdf/
// License: MIT
//
// Code by luk77 based on: 
// https://en.wikipedia.org/wiki/Tetrakis_hexahedron
// https://en.wikipedia.org/wiki/Truncated_octahedron
// Dual polyhedron: Tetrakis Hexahedron
float hgsdfTruncatedOctahedronHard(vec3 p, float r)
{
    const float a = 1.5f;
    const float b = 1.0 / 1.5f;

    const vec3 v0   = vec3( 1, 1, 1);
    const vec3 v1   = vec3( 1, 1,-1);
    const vec3 v2   = vec3( 1,-1, 1);
    const vec3 v3   = vec3( 1,-1,-1);
    const vec3 v8   = vec3( a, 0, 0);
    const vec3 v10  = vec3( 0, a, 0);
    const vec3 v12  = vec3( 0, 0, a);

    float d = 0.0;
    d = max(d, abs(dot(p, v0 )) * b);
    d = max(d, abs(dot(p, v1 )) * b);
    d = max(d, abs(dot(p, v2 )) * b);
    d = max(d, abs(dot(p, v3 )) * b);
    d = max(d, abs(dot(p, v8 )) * b);
    d = max(d, abs(dot(p, v10)) * b);
    d = max(d, abs(dot(p, v12)) * b);

    return d - r;
}
